// Author: MiYu. The original multiplayer lobby presents server slot state without starting an unverified game.
#include "lan_lobby.h"
#include <algorithm>
#include <cmath>

namespace war3 {
namespace {
std::string prefix(unsigned row){return "lan-slot-"+std::to_string(row);}
std::string display(std::string_view value){try{return utf8(wide(value));}catch(const std::exception&){if(value.empty())return {};int count=MultiByteToWideChar(CP_ACP,0,value.data(),int(value.size()),nullptr,0);if(count<=0)return "?";std::wstring text(count,L'\0');if(!MultiByteToWideChar(CP_ACP,0,value.data(),int(value.size()),text.data(),count))return "?";return utf8(text);}}
std::string safeChat(std::string_view value){auto source=display(value);std::string out;out.reserve(source.size());for(unsigned char c:source){if(c<32 || c==127)continue;if(c=='|')out+="\xef\xbd\x9c";else out+=char(c);}return out;}
bool inRect(GlueScreen::Rect r,float x,float y){return x>=r.x && y>=r.y && x<r.x+r.w && y<r.y+r.h;}
std::string raceName(GlueScreen& screen,unsigned race){if(race&32)return screen.localized("RANDOM");if(race&1)return screen.localized("HUMAN");if(race&2)return screen.localized("ORC");if(race&4)return screen.localized("NIGHT_ELF");if(race&8)return screen.localized("UNDEAD");return "?";}
}
LanLobby::LanLobby(Archives& archives,Images& images,Renderer& renderer,Text& text,const LanGame& game,std::string playerName) : screen_(archives,images,renderer,text,"UI\\FrameDef\\Glue\\GameChatroom.fdf","GameChatroom"),archives_(archives),game_(game),playerName_(std::move(playerName)),join_(std::make_unique<LanJoin>(game,playerName_)) {
    screen_.focusEnabled(false);screen_.attach("UI\\FrameDef\\Glue\\TeamSetup.fdf","TeamSetup","TeamSetupContainer");for(unsigned i=0;i<16;++i){auto ctx=prefix(i);screen_.attach("UI\\FrameDef\\Glue\\PlayerSlot.fdf","PlayerSlot","TeamSetup",ctx);screen_.visible(ctx+"/PlayerSlot",false);}screen_.setText("GameNameValue",display(game_.name));
}
void LanLobby::updateSlots(){
    auto& slots=join_->slots();auto& players=join_->players();auto bounds=screen_.bounds("TeamSetupContainer");float height=screen_.bounds(prefix(0)+"/PlayerSlot").h;if(height<=0)throw std::runtime_error("Invalid LAN player slot height");unsigned capacity=std::min(16u,std::max(1u,unsigned(std::floor((bounds.h-.02f)/height))));size_t maximum=slots.size()>capacity?slots.size()-capacity:0;scroll_=std::min(scroll_,maximum);std::string snapshot=std::to_string(scroll_)+":";for(auto& slot:slots){snapshot+=std::to_string(slot.playerId)+","+std::to_string(slot.download)+","+std::to_string(slot.status)+","+std::to_string(slot.computer)+","+std::to_string(slot.team)+","+std::to_string(slot.color)+","+std::to_string(slot.race)+","+std::to_string(slot.handicap)+";";}for(auto& player:players)snapshot+=std::to_string(player.id)+":"+std::to_string(player.name.size())+":"+player.name+";";if(snapshot==snapshot_)return;snapshot_=std::move(snapshot);
    for(unsigned row=0;row<16;++row){auto ctx=prefix(row);bool visible=row<capacity && scroll_+row<slots.size();screen_.visible(ctx+"/PlayerSlot",visible);if(!visible)continue;auto& slot=slots[scroll_+row];screen_.place(ctx+"/PlayerSlot",{bounds.x,bounds.y+.02f+float(row)*height,bounds.w,height});std::string name;if(slot.status==0)name=screen_.localized("OPEN");else if(slot.status==1)name=screen_.localized("CLOSED");else if(slot.computer)name=screen_.localized("COMPUTER_NORMAL");else{auto found=std::find_if(players.begin(),players.end(),[&](auto& p){return p.id==slot.playerId;});name=found!=players.end()?display(found->name):slot.playerId==join_->localPlayerId()?display(playerName_):"Player "+std::to_string(slot.playerId);}screen_.choices(ctx+"/NameMenu",{{name,{}}},0,.22f);screen_.choices(ctx+"/RaceMenu",{{raceName(screen_,slot.race),{}}},0,.12f);screen_.choices(ctx+"/TeamButton",{{std::to_string(unsigned(slot.team)+1),{}}},0,.12f);screen_.choices(ctx+"/ColorButton",{{{}, {}}},0,.08f,false);if(slot.color<16){auto color="ReplaceableTextures\\TeamColor\\TeamColor"+std::string(slot.color<10?"0":"")+std::to_string(slot.color)+".blp";screen_.image(ctx+"/ColorButtonValue",color);}screen_.choices(ctx+"/HandicapMenu",{{std::to_string(unsigned(slot.handicap))+"%",{}}},0,.08f);screen_.setText(ctx+"/DownloadValue",slot.status==2 && slot.download<=100?std::to_string(unsigned(slot.download))+"%":"");
    }
}
void LanLobby::updateMapCheck() {
    if(join_->state()!=LanJoinState::Lobby){if(mapTask_){mapTask_->cancel();mapTask_.reset();}expectedMap_.reset();mapStatus_=MapStatus::Waiting;mapError_.clear();return;}auto& announced=join_->mapCheck();if(!announced.received)return;bool changed=!expectedMap_ || expectedMap_->path!=announced.path || expectedMap_->size!=announced.size || expectedMap_->info!=announced.info || expectedMap_->crc!=announced.crc || expectedMap_->sha1!=announced.sha1;if(changed){if(mapTask_){mapTask_->cancel();mapTask_.reset();}expectedMap_=announced;mapStatus_=MapStatus::WaitingWorker;mapError_.clear();nextMapAttempt_=0;}
    if(mapStatus_==MapStatus::WaitingWorker && GetTickCount64()>=nextMapAttempt_){try{mapTask_=std::make_unique<LanMapCheckTask>(archives_,announced.path);mapStatus_=MapStatus::Checking;}catch(const LanMapCheckBusy&){nextMapAttempt_=GetTickCount64()+1000;}catch(const std::exception& e){mapStatus_=MapStatus::Failed;mapError_=e.what();}}
    if(mapTask_){auto result=mapTask_->poll();if(!result)return;if(!result->value){mapStatus_=MapStatus::Failed;mapError_=result->error;}else{auto& actual=*result->value;mapStatus_=actual.size==announced.size && actual.info==announced.info && actual.crc==announced.crc && actual.sha1==announced.sha1?MapStatus::Matched:MapStatus::Mismatch;}mapTask_.reset();}
}
std::string LanLobby::draw(const UiInput& input,std::wstring_view characters){
    if(input.key==VK_ESCAPE){join_->cancel();return "CancelButton";}try{join_->poll();updateMapCheck();}catch(const std::exception& e){error_=e.what();}auto bounds=screen_.bounds("TeamSetupContainer");if(input.wheel && input.x>=bounds.x && input.y>=bounds.y && input.x<bounds.x+bounds.w && input.y<bounds.y+bounds.h){float height=screen_.bounds(prefix(0)+"/PlayerSlot").h;unsigned capacity=height>0?std::min(16u,std::max(1u,unsigned(std::floor((bounds.h-.02f)/height)))):1;auto maximum=join_->slots().size()>capacity?join_->slots().size()-capacity:0;scroll_=size_t(std::clamp<long long>(static_cast<long long>(scroll_)-input.wheel,0,static_cast<long long>(maximum)));}updateSlots();auto edit=screen_.bounds("ChatEditBox"),history=screen_.bounds("ChatTextArea");if(input.pressed)chatFocus_=inRect(edit,input.x,input.y) && inRect(edit,input.startX,input.startY);if(input.key==VK_TAB)chatFocus_=!chatFocus_;auto state=join_->state();if(chatFocus_ && state==LanJoinState::Lobby){for(wchar_t c:characters){if(c==8){chatHighSurrogate_=0;if(!chatDraft_.empty()){if(chatDraft_.back()>=0xdc00 && chatDraft_.back()<=0xdfff && chatDraft_.size()>1)chatDraft_.pop_back();chatDraft_.pop_back();}}else if(c>=0xd800 && c<=0xdbff)chatHighSurrogate_=c;else if(c>=0xdc00 && c<=0xdfff){if(chatHighSurrogate_){auto next=chatDraft_;next+=chatHighSurrogate_;next+=c;if(utf8(next).size()<=254)chatDraft_=std::move(next);}chatHighSurrogate_=0;}else{chatHighSurrogate_=0;if(c>=32 && c!=127){auto next=chatDraft_+c;if(utf8(next).size()<=254)chatDraft_=std::move(next);}}}if(input.key==VK_RETURN && !chatDraft_.empty()){if(join_->sendChat(utf8(chatDraft_))){chatDraft_.clear();chatError_.clear();}else chatError_="无法发送聊天消息。";}}auto controls=input;if(chatFocus_)controls.key=0;auto action=screen_.draw("GameChatroom",controls,{"CancelButton"},true);screen_.backdropAt("StandardEditBoxBackdropTemplate",edit);screen_.textAt("StandardEditBoxTextTemplate",safeChat(utf8(chatDraft_)),{edit.x+.005f,edit.y,edit.w-.01f,edit.h},state==LanJoinState::Lobby,false,true,.012f);auto& messages=join_->chat();constexpr float line=.014f;auto rows=std::max<size_t>(1,size_t(std::max(0.f,history.h)/line));auto first=messages.size()>rows?messages.size()-rows:0;for(size_t i=first;i<messages.size();++i){auto& entry=messages[i];auto sender=std::find_if(join_->players().begin(),join_->players().end(),[&](const auto& p){return p.id==entry.sender;});auto name=sender==join_->players().end()?"Player "+std::to_string(entry.sender):safeChat(sender->name);auto value=name+": "+safeChat(entry.text);screen_.textAt("StandardInfoTextTemplate",value,{history.x,history.y+float(i-first)*line,history.w,line},true,false,true,.011f);}std::string status;if(!error_.empty())status="连接错误："+display(error_);else if(state==LanJoinState::Connecting)status="正在连接房间…";else if(state==LanJoinState::Joining)status="正在加入房间…";else if(state==LanJoinState::Lobby){switch(mapStatus_){case MapStatus::Waiting:status="已加入房间，等待主机地图信息。";break;case MapStatus::WaitingWorker:status="正在等待地图校验资源。";break;case MapStatus::Checking:status="正在校验本地地图…";break;case MapStatus::Matched:status="地图校验一致；对局同步尚未实现。";break;case MapStatus::Mismatch:status="本地地图与主机校验不一致，无法开始。";break;case MapStatus::Failed:status="地图校验失败："+display(mapError_);break;}}else if(state==LanJoinState::Rejected)status="主机拒绝加入（"+std::to_string(join_->rejectionCode())+"）";else if(state==LanJoinState::Closed)status="连接已关闭。";else status="连接失败："+display(join_->error());screen_.textAt("StandardInfoTextTemplate",status,{bounds.x,bounds.y+bounds.h+.004f,bounds.w,.024f},true,false,true,.011f);screen_.textAt("StandardInfoTextTemplate",display(game_.mapPath),screen_.bounds("MapInfoPaneContainer"),true,false,true,.011f);if(!chatError_.empty())screen_.textAt("StandardInfoTextTemplate",chatError_,{edit.x,edit.y-.015f,edit.w,.014f},true,false,true,.011f);screen_.overlay();if(action=="CancelButton"){join_->cancel();return action;}return {};
}
}
